#101719}.eyebrow{font:9px var(--mono);letter-spacing:.17em;color:#c5d0c7;display:flex;align-items:center;gap:9px}.eyebrow-line{width:20px;height:1px;background:var(--acid);display:inline-block}.eyebrow>span:last-child:not(.eyebrow-line){margin-left:auto;color:#7f9189}.mission-card h1{font-size:46px;line-height:1.04;letter-spacing:-.055em;margin:19px 0 14px;font-weight:600}.mission-card h1 em,.assembly-head h2 em,.start-card h1 em{font-style:normal;color:var(--acid)}.mission-card p{color:#d1d9d2;font-size:13px;line-height:1.8;margin:0 0 26px}.mission-progress{padding:14px 0 17px;border-top:1px solid rgba(238,246,236,.18);border-bottom:1px solid rgba(238,246,236,.18)}.progress-copy{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.12em;color:#b8c5bd}.progress-copy strong{font-weight:400;color:var(--acid)}.progress-track{height:3px;margin-top:10px;background:rgba(255,255,255,.18)}.progress-track i{height:100%;display:block;width:0;background:var(--acid);transition:width .5s}.primary-button{background:var(--acid);color:#18211e;border:0;padding:0 17px 0 19px;height:48px;display:flex;align-items:center;justify-content:space-between;min-width:100%;font:500 10px var(--mono);letter-spacing:.11em;cursor:pointer;transition:background .2s,transform .2s}.primary-button:hover:not(:disabled){background:#e5ff78;transform:translateY(-2px)}.primary-button b{font-size:17px;font-weight:400}.mission-card>.primary-button{margin-top:16px}.help-row{margin-top:19px;display:flex;align-items:center;gap:4px;color:#c3cdc5;font:8px var(--mono);letter-spacing:.06em}.help-row kbd,.interact-hint kbd{font:9px var(--mono);border:1px solid rgba(226,237,226,.47);padding:4px 5px;color:#ecf0e9;border-radius:2px;margin-right:2px}.help-row span{margin:0 9px 0 3px}.objective-chip{position:absolute;right:4.2vw;top:106px;z-index:3;display:flex;align-items:center;gap:12px;padding:12px 14px;width:255px;background:rgba(12,20,21,.58);border:1px solid rgba(226,238,230,.22);backdrop-filter:blur(8px)}.chip-icon{font-size:21px;color:var(--acid)}.objective-chip small{display:block;font:8px var(--mono);letter-spacing:.16em;color:#b2c0b7;margin-bottom:4px}.objective-chip b{font-size:10px;font-weight:600}.chip-arrow{margin-left:auto;color:#b0beb5}.bottom-note{position:absolute;bottom:22px;left:4.2vw;z-index:3;color:#b5c0ba;font:8px var(--mono);letter-spacing:.14em}.bottom-note span{color:var(--acid)}.bottom-note i{font-style:normal;padding:0 8px;color:#697972}.interact-hint{position:absolute;z-index:3;left:50%;bottom:16%;transform:translateX(-50%);display:none;align-items:center;gap:9px;padding:10px 13px;background:rgba(12,20,21,.8);border:1px solid rgba(230,244,232,.28);font:9px var(--mono);letter-spacing:.12em}.interact-hint.visible{display:flex}.crosshair{display:none;z-index:2;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:17px;height:17px;opacity:.7}.crosshair.show{display:block}.crosshair i,.crosshair b{position:absolute;background:var(--acid)}.crosshair i{width:1px;height:17px;left:8px}.crosshair b{width:17px;height:1px;top:8px}.minimap-frame{display:none;position:absolute;right:4.2vw;bottom:35px;z-index:3;padding:10px;background:rgba(10,17,18,.75);border:1px solid rgba(226,238,230,.24)}.minimap-frame.show{display:block}.mini-label{font:8px var(--mono);letter-spacing:.12em;margin-bottom:7px;color:#aebbb3}.mini-label b{color:var(--acid);font-weight:400}.minimap-frame canvas{display:block;width:100px;height:100px;opacity:.85}.drive-hud{display:none;position:absolute;z-index:3;bottom:38px;left:50%;transform:translateX(-50%);padding:13px 18px;min-width:310px;background:rgba(10,17,18,.8);border:1px solid rgba(226,238,230,.25);align-items:center;gap:18px}.drive-hud.show{display:flex}.drive-hud small{display:block;font:8px var(--mono);letter-spacing:.15em;color:#adbbb1}.drive-hud strong{font:25px var(--mono);color:var(--acid)}.drive-hud strong i{font:9px var(--mono);color:#c6d0c7}.gear{font:19px var(--mono);color:#eaf0e8;border-left:1px solid #54615b;padding-left:17px}.drive-tip{max-width:118px;color:#aebbb3;font:8px/1.8 var(--mono);letter-spacing:.05em}.drive-tip span{color:var(--acid)}.toast{position:absolute;z-index:9;left:50%;top:20%;transform:translate(-50%,-8px);padding:12px 18px;background:var(--acid);color:#17201d;font:10px var(--mono);letter-spacing:.09em;opacity:0;pointer-events:none;transition:.3s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{display:none;position:absolute;inset:0;z-index:10;background:rgba(7,12,13,.83);backdrop-filter:blur(10px);padding:5vh 5vw;align-items:center;justify-content:center}.modal-backdrop.open{display:flex}.assembly-window{width:min(1100px,100%);height:min(750px,92vh);background:#e9ede5;color:#18201d;display:flex;flex-direction:column;box-shadow:0 24px 90px rgba(0,0,0,.5)}.assembly-head{height:116px;flex-shrink:0;padding:25px 31px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #cbd2c8}.assembly-head .eyebrow{color:#66726a}.assembly-head h2{font-size:27px;line-height:1;margin:11px 0 0;font-weight:600;letter-spacing:-.05em}.assembly-head h2 em{color:#7b9800}.close-button{width:38px;height:38px;border:1px solid #aeb8ac;background:none;color:#27312b;font-size:25px;line-height:1;cursor:pointer}.assembly-body{display:grid;grid-template-columns:280px 1fr;min-height:0;flex:1}.parts-panel{padding:25px 20px 20px 30px;border-right:1px solid #cbd2c8;display:flex;flex-direction:column}.panel-kicker{font:9px var(--mono);letter-spacing:.13em;color:#7d887f;margin-bottom:13px}.part-card{display:grid;grid-template-columns:43px 1fr 22px;gap:10px;align-items:center;text-align:left;width:100%;padding:11px 8px;border:0;border-bottom:1px solid #d3d9d0;color:#1c2520;background:transparent;cursor:pointer;transition:.18s}.part-card:hover,.part-card.selected{background:#dce7c9}.part-card.locked{opacity:.38;cursor:not-allowed}.part-icon{height:38px;width:38px;background:#dce3d8;display:grid;place-items:center;color:#455342;font-size:20px}.part-card strong{display:block;font-size:10px;font-weight:700}.part-card small{display:block;color:#718075;font:8px var(--mono);margin-top:4px}.part-card .part-cost{font:9px var(--mono);color:#829000}.part-card.installed .part-icon{background:#d8ff3e;color:#253019}.parts-note{margin-top:auto;color:#758078;font:9px/1.7 var(--mono)}.blueprint-panel{padding:25px 30px 21px;display:flex;flex-direction:column;min-width:0}.blueprint-top{display:flex;justify-content:space-between;color:#6b786f;font:9px var(--mono);letter-spacing:.13em}.blueprint-top i{color:#94a40b;font-style:normal}.blueprint-status{color:#8e9f04}.blueprint-stage{position:relative;flex:1;min-height:250px;max-height:430px;margin:12px 0;background:#e2e8de;overflow:hidden}.blueprint-grid{position:absolute;inset:0;opacity:.34;background-image:linear-gradient(rgba(63,94,66,.14) 1px,transparent 1px),linear-gradient(90deg,rgba(63,94,66,.14) 1px,transparent 1px);background-size:22px 22px}.vehicle-blueprint{position:absolute;width:100%;height:100%;inset:0}.blueprint-line{fill:rgba(101,132,91,.08);stroke:#637c5b;stroke-width:3}.blueprint-line.faint{fill:none;stroke:#879782;stroke-width:2;stroke-dasharray:6 5}.wheel-guide{fill:#e2e8de;stroke:#758571;stroke-width:3;stroke-dasharray:6 4}.hub-guide{fill:none;stroke:#9ba791;stroke-width:2}.slot{cursor:pointer}.slot circle{fill:#e6ecd9;stroke:#788c45;stroke-width:2;transition:.2s}.slot:hover circle,.slot.active circle{fill:#d8ff3e;stroke:#3e4c24}.slot text{fill:#526046;text-anchor:middle;font:10px var(--mono);pointer-events:none}.slot.complete circle{fill:#d8ff3e;stroke:#728b24}.part-built{stroke:#3f5942;stroke-width:3;fill:#9eb48d}.part-built.accent{fill:#d8ff3e}.blueprint-caption{position:absolute;bottom:12px;left:17px;right:17px;display:flex;gap:30px;font:8px var(--mono);letter-spacing:.1em;color:#7b877c}.blueprint-caption b{color:#303b32;font-weight:500;margin-left:5px}.assembly-footer{display:flex;align-items:center;justify-content:space-between;min-height:50px;color:#6d786f;font:9px var(--mono)}.launch-button{min-width:175px;height:43px}.launch-button:disabled{background:#c9d0c6;color:#788178;cursor:not-allowed;transform:none}.start-screen{position:absolute;z-index:8;inset:0;background:linear-gradient(90deg,rgba(8,14,16,.97) 0%,rgba(8,14,16,.78) 44%,rgba(8,14,16,.1) 100%);display:flex;align-items:center;padding-left:12vw;transition:opacity .7s,visibility .7s}.start-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-card{width:410px;border-left:1px solid var(--acid);padding-left:24px}.start-card h1{font-size:52px;line-height:1.02;letter-spacing:-.06em;margin:22px 0 14px;font-weight:600}.start-card p{max-width:340px;color:#c1cbc3;font-size:13px;line-height:1.8;margin:0 0 23px}.start-card .primary-button{width:260px;min-width:260px}.start-foot{margin-top:18px;color:#aab7af;font:8px var(--mono);letter-spacing:.14em}.start-foot span{color:var(--acid);padding:0 6px}.start-stamp{position:absolute;right:8vw;bottom:9vh;border:1px solid rgba(216,255,62,.65);width:92px;height:92px;display:grid;place-content:center;text-align:center;color:var(--acid);font:28px var(--mono);transform:rotate(-9deg)}.start-stamp small{font-size:7px;letter-spacing:.12em}.hidden-ui{display:none!important}
@media(max-width:760px){.topbar{height:66px;padding:0 18px}.location{font-size:8px}.icon-button span{display:none}.mission-card{left:7vw;width:min(330px,84vw);top:53%;padding-left:16px}.mission-card h1{font-size:39px}.objective-chip{right:15px;top:80px;width:225px;padding:9px}.bottom-note{left:18px;bottom:15px;font-size:7px}.start-screen{padding:0 8vw;background:linear-gradient(90deg,rgba(8,14,16,.94),rgba(8,14,16,.65))}.start-card{width:100%;padding-left:18px}.start-card h1{font-size:42px}.start-stamp{right:9vw;bottom:7vh;width:68px;height:68px;font-size:22px}.start-card .primary-button{width:100%;min-width:0}.help-row{flex-wrap:wrap;font-size:7px}.modal-backdrop{padding:0;align-items:stretch}.assembly-window{height:100vh;width:100%;overflow:auto}.assembly-head{height:92px;padding:18px}.assembly-head h2{font-size:22px}.assembly-body{display:flex;flex-direction:column}.parts-panel{order:2;padding:15px 16px;display:grid;grid-template-columns:1fr 1fr;gap:0 8px;border-right:0;border-top:1px solid #cbd2c8}.panel-kicker,.parts-note{grid-column:1/-1}.part-card{grid-template-columns:35px 1fr 15px;padding:8px 4px;gap:7px}.part-icon{width:32px;height:32px}.part-card strong{font-size:9px}.part-card small{font-size:7px}.parts-note{margin:12px 0 0}.blueprint-panel{order:1;padding:16px}.blueprint-stage{height:260px;flex:none}.blueprint-caption{gap:12px;font-size:7px}.assembly-footer{gap:10px;font-size:8px}.launch-button{min-width:145px;font-size:8px}.drive-hud{bottom:22px;min-width:0;width:90%;justify-content:center;padding:10px}.drive-tip{max-width:105px;font-size:7px}.minimap-frame{right:12px;bottom:100px;padding:7px}.minimap-frame canvas{width:72px;height:72px}.interact-hint{bottom:22%}}

(() => {
  'use strict';
  const canvas = document.getElementById('view'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const mapW = 92, mapH = 20, world = Array.from({length: mapH}, () => Array(mapW).fill(0));
  // 0 = open, 1 = workshop concrete, 2 = warm brick, 3 = glass / painted city facade
  for (let y=0;y<mapH;y++) for(let x=0;x<mapW;x++) {
    if (x===0 || y===0 || y===mapH-1 || x===mapW-1) world[y][x]=3;
    if (x<=15 && y<=13 && (x===1 || y===1 || y===13 || (x===15 && !(y>=5&&y<=8)))) world[y][x]=1;
    if (x>15 && x<mapW-1 && (y<=2 || y>=17)) world[y][x]=((Math.floor(x/9)%3)===0?2:3);
    // periodic side-street openings and little facade setbacks
    if (x>16 && x<mapW-1 && (x%27===0 || x%27===1) && y>=2 && y<=17) world[y][x]=0;
  }
  const player={x:6.1,y:7,angle:0}, keys={};
  let mode='walk', started=false, modal=false, selected=null, driving=false, speed=0, steer=0, lookDelta=0, walkBob=0, clock=0, toastTimer=0;
  let soundOn=false;
  const required=[
    {id:'chassis',name:'Châssis tubulaire',desc:'Cadre acier · base légère',icon:'⌑',power:'—',mass:'38 kg'},
    {id:'engine',name:'Moteur 2 cylindres',desc:'620 cm³ · refroidi par air',icon:'⚙',power:'42 ch',mass:'64 kg'},
    {id:'seat',name:'Siège baquet',desc:'Fibre tressée · 1 place',icon:'▰',power:'—',mass:'8 kg'},
    {id:'wheels',name:'4 roues tout-terrain',desc:'Pneus mixtes · jantes alu',icon:'◉',power:'ADH.',mass:'32 kg'},
    {id:'steering',name:'Direction directe',desc:'Volant + crémaillère',icon:'⊗',power:'CTRL',mass:'11 kg'},
    {id:'battery',name:'Batterie compacte',desc:'12 V · démarrage électrique',icon:'▣',power:'12 V',mass:'9 kg'}
  ];
  const installed=new Set();
  let w=innerWidth,h=innerHeight,dpr=Math.min(devicePixelRatio||1,1.65),zBuffer=[];
  function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,1.65);canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr);canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0);}
  addEventListener('resize',resize);resize();
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function cell(x,y){const ix=Math.floor(x),iy=Math.floor(y);return world[iy]?.[ix] ?? 3;}
  function blocked(x,y){return cell(x+.18,y)!==0||cell(x-.18,y)!==0||cell(x,y+.18)!==0||cell(x,y-.18)!==0;}
  function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');toastTimer=2.4;}
  function setModal(open){modal=open;$('assemblyModal').classList.toggle('open',open);$('assemblyModal').setAttribute('aria-hidden',String(!open));if(open){$('crosshair').classList.remove('show');document.exitPointerLock?.();}else if(started)$('crosshair').classList.add('show');}
  function drawParts(){
    const list=$('partsList'); list.innerHTML='';
    required.forEach((p,i)=>{const done=installed.has(p.id), blockedItem=i>0&&!installed.has('chassis')&&!done;
      const b=document.createElement('button');b.className='part-card'+(done?' installed':'')+(selected===p.id?' selected':'')+(blockedItem?' locked':'');b.disabled=done||blockedItem;
      b.innerHTML=`<span class="part-icon">${done?'✓':p.icon}</span><span><strong>${p.name}</strong><small>${done?'INSTALLÉE':p.desc}</small></span><span class="part-cost">${done?'✓':'+'}</span>`;
      b.onclick=()=>{selected=p.id;drawParts();document.querySelectorAll('.slot').forEach(s=>s.classList.toggle('active',s.dataset.slot===p.id));$('assemblyMessage').textContent=`${p.name} sélectionné · choisis son emplacement sur le plan.`;};list.appendChild(b);
    });
    updateAssembly();
  }
  function updateAssembly(){
    const n=installed.size;$('progressText').textContent=`${n} / 6 PIÈCES`;$('progressBar').style.width=`${n/6*100}%`;
    $('buildStatus').textContent=n===0?'CHÂSSIS NU':n===6?'PRÊT À ROULER':'ASSEMBLAGE · '+n+'/6';
    $('powerReadout').textContent=installed.has('engine')?'42 CH':'—';
    let mass=0;required.forEach(p=>{if(installed.has(p.id))mass+=parseInt(p.mass)||0;});$('massReadout').textContent=mass?`${mass} KG`:'—';
    document.querySelectorAll('.slot').forEach(s=>s.classList.toggle('complete',installed.has(s.dataset.slot)));
    const visuals=$('partVisuals'); visuals.innerHTML='';
    if(installed.has('chassis')) visuals.insertAdjacentHTML('beforeend','<path class="part-built accent" d="M121 210 L179 169 L430 169 L499 210 L486 220 L139 220 Z"/>');
    if(installed.has('engine')) visuals.insertAdjacentHTML('beforeend','<rect class="part-built" x="371" y="180" width="57" height="32" rx="4"/><path class="part-built accent" d="M380 178h39v-7h-39z"/>');
    if(installed.has('seat')) visuals.insertAdjacentHTML('beforeend','<path class="part-built" d="M245 143 Q248 136 258 137h29q8 0 9 9l-3 16h-42z"/>');
    if(installed.has('wheels')) visuals.insertAdjacentHTML('beforeend','<g><circle cx="190" cy="249" r="30" fill="#344038" stroke="#d8ff3e" stroke-width="5"/><circle cx="190" cy="249" r="11" fill="#b7c5a5"/><circle cx="426" cy="249" r="30" fill="#344038" stroke="#d8ff3e" stroke-width="5"/><circle cx="426" cy="249" r="11" fill="#b7c5a5"/></g>');
    if(installed.has('steering')) visuals.insertAdjacentHTML('beforeend','<path class="part-built accent" d="M235 161a12 12 0 1 1 24 0 M247 161l12 10" fill="none"/>');
    if(installed.has('battery')) visuals.insertAdjacentHTML('beforeend','<rect class="part-built accent" x="316" y="177" width="34" height="20" rx="3"/>');
    $('launchButton').disabled=n!==6;
    if(n===6){$('assemblyMessage').textContent='Tout est en place. La ville t’attend.';$('objectiveText').textContent='Véhicule assemblé · prêt pour l’essai';}
  }
  drawParts();
  document.querySelectorAll('.slot').forEach(slot=>slot.addEventListener('click',()=>{
    const id=slot.dataset.slot;if(!selected){$('assemblyMessage').textContent='Choisis une pièce dans la liste à gauche.';return;}
    if(id!==selected){$('assemblyMessage').textContent='Cette pièce ne correspond pas à cet emplacement.';return;}
    installed.add(id);selected=null;drawParts();$('assemblyMessage').textContent=`${required.find(p=>p.id===id).name} installé.`;
    if(installed.size===6)toast('PROTOTYPE 09 TERMINÉ — ESSAI DISPONIBLE');
  }));
  $('buildButton').onclick=()=>setModal(true);$('closeAssembly').onclick=()=>setModal(false);
  $('launchButton').onclick=()=>{if(installed.size<6)return;setModal(false);started=true;mode='drive';driving=true;speed=0;player.x=16.5;player.y=7;player.angle=0;$('startScreen').classList.add('hidden');$('missionCard').classList.add('hidden-ui');$('objectiveChip').classList.add('hidden-ui');$('locationLabel').textContent='RUE DES FORGES · V-09';$('driveHud').classList.add('show');$('minimapFrame').classList.add('show');$('crosshair').classList.add('show');toast('ESSAI ROUTIER — PRENDS LA RUE VERS L’EST');};
  $('startButton').onclick=()=>{started=true;$('startScreen').classList.add('hidden');$('crosshair').classList.add('show');$('missionCard').classList.remove('hidden-ui');};
  $('soundButton').onclick=()=>{soundOn=!soundOn;$('soundButton').innerHTML=soundOn?'♫ <span>ON</span>':'♫ <span>SON</span>';toast(soundOn?'SON ACTIVÉ':'SON COUPÉ');};
  addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key.toLowerCase()==='e'&&started&&!modal&&!driving){if(Math.hypot(player.x-10.6,player.y-7)<3.6)setModal(true);}});
  addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
  canvas.addEventListener('click',()=>{if(started&&!modal&&canvas.requestPointerLock&&!('ontouchstart'in window))canvas.requestPointerLock();});
